create table if not exists public.post_media(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.user_posts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,media_path text not null,media_type text not null check(media_type in('image','video')),position integer not null check(position between 0 and 14),duration_ms integer,created_at timestamptz not null default now(),constraint post_media_path_unique unique(media_path),constraint post_media_post_position_unique unique(post_id,position),constraint post_media_duration_check check((media_type='image' and duration_ms is null) or (media_type='video' and (duration_ms is null or duration_ms>=0))));create index if not exists post_media_post_position_idx on public.post_media(post_id,position);alter table public.post_media enable row level security;revoke all on public.post_media from anon,authenticated;grant select,insert,delete on public.post_media to authenticated;create policy post_media_read_visible on public.post_media for select to authenticated using(exists(select 1 from public.user_posts p where p.id=post_id and (p.user_id=(select auth.uid()) or (p.visibility='public' and p.moderation_status='published'))));create policy post_media_insert_owner on public.post_media for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.user_posts p where p.id=post_id and p.user_id=(select auth.uid())));create policy post_media_delete_owner on public.post_media for delete to authenticated using(user_id=(select auth.uid()) and exists(select 1 from public.user_posts p where p.id=post_id and p.user_id=(select auth.uid())));